/**
 * Problem: LeetCode 190 - Reverse Bits
 * Difficulty: Easy
 * Language: Java
 * Author: CodeByTushu
 */
public class Solution {
    // you need treat n as an unsigned value
    public int reverseBits(int n) {
        int result = 0;
        for (int i = 0; i < 32; i++) {
            result = (result << 1) | (n & 1);
            n >>>= 1;
        }
        return result;
    }
}

